<main class="content container-fluid"><div class="page-toolbar"><a class="btn btn-outline-secondary" href="<?=url('/admin/usuarios')?>">← Volver a usuarios</a></div><section class="card panel-card form-card mx-auto"><div class="card-body p-4 p-lg-5"><span class="eyebrow">CUENTA DE USUARIO</span><h2 class="mt-2 mb-1"><?=$user?'Editar usuario':'Crear usuario'?></h2><p class="text-secondary mb-4">Completa los datos, asigna el rol y define los módulos disponibles.</p><form method="post" action="<?=url('/admin/usuarios/guardar')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($user['id']??'')?>"><div class="row g-4"><div class="col-md-6"><label class="form-label">Nombre</label><input class="form-control" required name="first_name" value="<?=e($user['first_name']??'')?>"></div><div class="col-md-6"><label class="form-label">Apellido</label><input class="form-control" required name="last_name" value="<?=e($user['last_name']??'')?>"></div><div class="col-md-6"><label class="form-label">Correo electrónico</label><input class="form-control" required type="email" name="email" value="<?=e($user['email']??'')?>"></div><div class="col-md-6"><label class="form-label">Teléfono</label><input class="form-control" name="phone" value="<?=e($user['phone']??'')?>"></div><div class="col-md-6"><label class="form-label">Rol</label><select class="form-select" required name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>" <?=($user['role_id']??null)==$r['id']?'selected':''?>><?=e(ucfirst($r['name']))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Asignatura</label><select class="form-select" name="subject_id"><option value="">Sin asignatura</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=($user['subject_id']??null)==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Contraseña</label><input class="form-control" type="password" name="password" minlength="8" <?=$user?'':'required'?> placeholder="<?=$user?'Déjala vacía para conservar la actual':'Crea una contraseña segura'?>"><div class="form-text">Usa al menos 8 caracteres y evita contraseñas reutilizadas.</div></div><div class="col-md-6"><div class="form-check permission-check"><input class="form-check-input" type="checkbox" id="test_enabled" name="test_enabled" value="1" <?=!empty($user['test_enabled'])?'checked':''?>><label class="form-check-label" for="test_enabled"><strong>Módulo de tests</strong><span>Permite acceder a las evaluaciones.</span></label></div></div><div class="col-md-6"><div class="form-check permission-check"><input class="form-check-input" type="checkbox" id="tabulator_enabled" name="tabulator_enabled" value="1" <?=!empty($user['tabulator_enabled'])?'checked':''?>><label class="form-check-label" for="tabulator_enabled"><strong>Módulo de tabuladores</strong><span>Permite revisar los tabuladores.</span></label></div></div><input type="hidden" name="active" value="1"></div><div class="form-footer"><a class="btn btn-outline-secondary" href="<?=url('/admin/usuarios')?>">Cancelar</a><button class="btn btn-brand" type="submit">Guardar usuario</button></div></form></div></section></main>
